        item_id, batch_id = cls._format_ids(item_id, batch_id)
        _size(size)
        prefix = f"{size}_" if size else ""
        item = f"{prefix}covers_{item_id}"
        return os.path.join("items", item, f"{item}_{batch_id}.{ext}")

    @classmethod
    def get_abspath(cls, item_id, batch_id, size="", ext="zip"):
        return os.path.join(
            config.data_root, cls.get_relpath(item_id, batch_id, size, ext)
        )

    @property
    def start_id(self):
        return int(self.item_id) * 1_000_000 + int(self.batch_id) * BATCH_SIZE

    @contextlib.contextmanager
    def lock(self):
        """Hold a process-wide exclusive lock for the batch while changing it."""
        lock_dir = os.path.join(config.data_root, "items", ".locks")
        os.makedirs(lock_dir, exist_ok=True)
        with open(
            os.path.join(lock_dir, f"{self.item_id}_{self.batch_id}.lock"), "a+b"
        ) as lockfile:
            fcntl.flock(lockfile, fcntl.LOCK_EX | fcntl.LOCK_NB)
            try:
                yield
            finally:
                fcntl.flock(lockfile, fcntl.LOCK_UN)

    def process_pending(self, upload=False, finalize=False, test=False, uploader=None):
        if finalize and self.size is not None:
            raise ValueError("finalization requires all size variants")
        uploader = uploader or Uploader()
        with self.lock():
            sizes = SIZES if self.size is None else (self.size,)
            pending = []
            for size in sizes:
                path = self.get_abspath(self.item_id, self.batch_id, size)
                if not os.path.isfile(path):
                    if finalize and self.size is None:
                        cover_db = CoverDB()
                        archived = cover_db.get_archived(self.start_id)
                        if archived and all(row.uploaded for row in archived):
                            return True
                    return False
                item = f'{size + "_" if size else ""}covers_{self.item_id}'
                pending.append((item, path))
            for item, path in pending:
                if not uploader.is_uploaded(item, os.path.basename(path)):
                    if not upload or test:
                        return False
                    uploader.upload(item, [path])
                    if not uploader.is_uploaded(item, os.path.basename(path)):
                        return False
            if finalize and not test and self.size is None:
                self._finalize_locked()
            return True

    def _finalize_locked(self):
        cover_db = CoverDB()
        covers = cover_db.get_batch(self.start_id, archived=True, uploaded=False)
        cover_db.update_completed_batch(self.item_id, self.batch_id)
        for row in covers:
            Cover(row).delete_files()
        for size in SIZES:
            os.remove(self.get_abspath(self.item_id, self.batch_id, size))

    def finalize(self, start_id=None, test=False, uploader=None):
        if start_id is not None and int(start_id) != self.start_id:
            raise ValueError("start id does not match batch")
        return self.process_pending(finalize=True, test=test, uploader=uploader)


class ZipManager:
    def __init__(self):
        self.zipfiles = {}
        self.members = {}

    def get_zipfile(self, name):
        cover_id = int(name[:10])
        size = name[11].lower() if len(name) > 10 and name[10] == "-" else ""
        item_id, batch_id = Cover.id_to_item_and_batch_id(cover_id)
        path = Batch.get_abspath(item_id, batch_id, size)
        if path not in self.zipfiles:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            archive = zipfile.ZipFile(
                path, "a", compression=zipfile.ZIP_STORED, allowZip64=True
            )
            self.zipfiles[path] = archive
            self.members[path] = set(archive.namelist())
        return self.zipfiles[path]

    def add_file(self, name, filepath, mtime):
        archive = self.get_zipfile(name)
        if name not in self.members[archive.filename]:
            info = zipfile.ZipInfo(name, time.localtime(mtime)[:6])
            info.compress_type = zipfile.ZIP_STORED
            with open(filepath, "rb") as source, archive.open(info, "w") as target:
                while chunk := source.read(1024 * 1024):
                    target.write(chunk)
            self.members[archive.filename].add(name)
        return archive.filename

    def close(self):
        for archive in self.zipfiles.values():
            archive.close()
        self.zipfiles.clear()
        self.members.clear()


def count_files_in_zip(filepath):
    with zipfile.ZipFile(filepath) as archive:
        return sum(name.lower().endswith(".jpg") for name in archive.namelist())


def open_zipfile(name):
    manager = ZipManager()
    return manager.get_zipfile(name)


def get_zipfile(name):
    return open_zipfile(name)


class Uploader:
    def upload(self, itemname, filepaths):
        return run(
            ["ia", "upload", itemname, *filepaths],
            check=True,
            capture_output=True,
            text=True,
        )

    @staticmethod
    def is_uploaded(item, zip_filename, verbose=False):
        result = run(["ia", "list", item], check=True, capture_output=True, text=True)
        names = {line.strip().split("/")[-1] for line in result.stdout.splitlines()}
        return zip_filename in names


class CoverDB:
    def __init__(self):
        self.db = db.getdb()

    @staticmethod
    def _get_batch_end_id(start_id):
        return (int(start_id) // BATCH_SIZE + 1) * BATCH_SIZE - 1

    def get_batch(self, start_id, archived=None, uploaded=None):
        end_id = self._get_batch_end_id(start_id)
        conditions = ["id >= $start_id", "id <= $end_id", "failed = $false"]
        values = {"start_id": start_id, "end_id": end_id, "false": False}
        if archived is not None:
            conditions.append("archived = $archived")
            values["archived"] = archived
        if uploaded is not None:
            conditions.append("uploaded = $uploaded")
            values["uploaded"] = uploaded
        return list(
            self.db.select(
                "cover", where=" AND ".join(conditions), vars=values, order="id"
            )
        )

    def get_unarchived(self, limit=10_000):
        return list(
            self.db.select(
                "cover",
                where="archived=$false AND failed=$false",
                vars={"false": False},
                order="id",
                limit=limit,
            )
        )

    def get_archived(self, start_id):
        return self.get_batch(start_id, archived=True)

    def get_failed(self, start_id):
        end_id = self._get_batch_end_id(start_id)
        return list(
            self.db.select(
                "cover",
                where="id >= $start_id AND id <= $end_id AND failed=$true",
                vars={"start_id": start_id, "end_id": end_id, "true": True},
            )
        )

    @staticmethod
    def update_completed_batch(item_id, batch_id, ext="jpg"):
        return CoverDB()._update_completed_batch(item_id, batch_id, ext)

    def _update_completed_batch(self, item_id, batch_id, ext="jpg"):
        start_id = int(item_id) * 1_000_000 + int(batch_id) * BATCH_SIZE
        rows = self.get_batch(start_id, archived=True, uploaded=False)
        transaction = self.db.transaction()
        try:
            for row in rows:
                self.db.update(
                    "cover",
                    where="id=$id AND archived=$true AND failed=$false AND uploaded=$false",
                    vars={"id": row.id, "true": True, "false": False},
                    uploaded=True,
                    filename=Cover.get_cover_url(row.id, ext=ext),
                    filename_s=Cover.get_cover_url(row.id, "s", ext),
                    filename_m=Cover.get_cover_url(row.id, "m", ext),
                    filename_l=Cover.get_cover_url(row.id, "l", ext),
                )
            transaction.commit()
        except Exception:
            transaction.rollback()
            raise
        return len(rows)


